// AI: below section was generated by an AI
// Bind discovery to the device's asynchronous WLED scan; SSIDs are always rendered as text.
export function wifiDiscovery($) {
	let scanning = false;
	let lastScan = 0;
	$("wifiDiscovery").hidden = false;
	$("wifiNetworks").onchange = () => {
		if (!$("wifiNetworks").value) return;
		$("ssid").value = $("wifiNetworks").value;
		$("wifiPassword").value = "";
		$("wifiPassword").focus();
	};
	$("ssid").oninput = () => { $("wifiNetworks").value = ""; };

	// Empty responses also mean scanning is still in progress, so poll with a bounded deadline.
	async function scan() {
		if (scanning) return;
		scanning = true;
		$("scanWifi").disabled = true;
		$("scanWifi").textContent = "Searching...";
		$("wifiScanStatus").textContent = "Searching for nearby Wi-Fi networks...";
		try {
			const signal = AbortSignal.timeout(15000);
			let networks = [];
			for (let attempt = 0; attempt < 12; attempt++) {
				const response = await fetch("/json/net", { cache: "no-store", signal });
				if (!response.ok) throw new Error("Wi-Fi search failed. Search again or enter the network name below.");
				const result = await response.json();
				if (!Array.isArray(result.networks)) throw new Error("Invalid Wi-Fi scan response. Please search again.");
				const strongest = new Map();
				for (const network of result.networks.slice(0, 512)) {
					if (typeof network.ssid !== "string" || !network.ssid.length || new TextEncoder().encode(network.ssid).length > 32 || !Number.isFinite(network.rssi)) continue;
					if (!strongest.has(network.ssid) || network.rssi > strongest.get(network.ssid).rssi) strongest.set(network.ssid, network);
				}
				networks = [...strongest.values()].sort((a, b) => b.rssi - a.rssi);
				if (networks.length) break;
				if (attempt < 11) await new Promise((resolve) => setTimeout(resolve, 750));
			}
			const select = $("wifiNetworks");
			select.replaceChildren(new Option("Choose a network", ""));
			for (const network of networks) select.add(new Option(network.ssid + " (" + network.rssi + " dBm)", network.ssid));
			select.value = $("ssid").value;
			$("wifiNetworkLabel").hidden = !networks.length;
			$("wifiScanStatus").textContent = networks.length
				? "Select your network, then enter its password. Hidden networks can be entered below."
				: "No networks found. Search again or enter the network name below.";
			lastScan = Date.now();
		} catch (error) {
			$("wifiScanStatus").textContent = error.name === "TimeoutError"
				? "Wi-Fi search timed out. Search again or enter the network name below."
				: error.message;
		} finally {
			scanning = false;
			$("scanWifi").disabled = false;
			$("scanWifi").textContent = "Search again";
		}
	}
	$("scanWifi").onclick = scan;
	return { open: () => { if (!lastScan || Date.now() - lastScan > 30000) return scan(); } };
}
// AI: end
